'use strict';

// Rebuild Hanna Laha's separate bank with its existing importer, from main's live base rows.
// npm ci is required in both repositories. No protocol, scoring or engine source is changed.
// Usage: node tools/hanna-room-bank-sync.cjs --hanna-root ../hanna-laha-room-sync
// The git reference defaults to origin/main. Generated bytes contain no clock or commit timestamp.
const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const ROOT = path.resolve(__dirname, '..');
const BANK = 'quest-data/kunuz-bank-3147.js';
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
const parseBank = bytes => {
  const text = bytes.toString('utf8').trimEnd();
  assert.ok(text.startsWith('var DATA=') && text.endsWith(';'), 'Unexpected bank wrapper');
  const data = JSON.parse(text.slice(9, -1));
  assert.ok(Array.isArray(data.cats) && Array.isArray(data.qs), 'Missing cats/qs');
  return data;
};
const isHeld = row => row[3] === '' && Array.isArray(row[4]) && row[4].length === 0 && row[5] === -1;
const roomId = (cat, prompt) => cat + '-' + sha(cat + '\0mcq\0' + prompt.trim()).slice(0, 8);
function liveBank(data) {
  const ids = new Set();
  for (const row of data.qs) {
    assert.ok(Array.isArray(row) && typeof row[8] === 'string' && !ids.has(row[8]), 'Missing/duplicate app id');
    ids.add(row[8]);
    assert.ok(Number.isInteger(row[0]) && data.cats[row[0]], 'Unknown base category');
    if (isHeld(row)) continue;
    assert.ok(typeof row[3] === 'string' && row[3].trim(), 'Unexpected empty live prompt');
    assert.ok(Array.isArray(row[4]) && row[4].length >= 2 && row[4].every(x => typeof x === 'string' && x.trim()), 'Invalid live choices');
    assert.ok(Number.isInteger(row[5]) && row[5] >= 0 && row[5] < row[4].length, 'Invalid live answer');
  }
  return {cats: data.cats, qs: data.qs.filter(row => !isHeld(row))};
}
function git(...args) {
  return cp.execFileSync('git', args, {cwd: ROOT, maxBuffer: 1 << 28, stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true});
}
function recoverHeld(data, ref) {
  const missing = new Set(data.qs.filter(isHeld).map(r => r[8]));
  const found = new Map();
  for (const commit of git('log', '--format=%H', ref, '--', BANK).toString().trim().split(/\s+/)) {
    if (!missing.size) break;
    const previous = parseBank(git('show', commit + ':' + BANK));
    for (const row of previous.qs) {
      if (!missing.has(row[8]) || isHeld(row) || !row[3]) continue;
      found.set(row[8], {appId: row[8], roomId: roomId(previous.cats[row[0]][0], row[3]), promptSha256: sha(row[3].trim())});
      missing.delete(row[8]);
    }
  }
  assert.equal(missing.size, 0, 'Could not recover original held rows from git history');
  return data.qs.filter(isHeld).map(r => found.get(r[8]));
}
function sync(hanna, ref = 'origin/main') {
  const bytes = git('show', ref + ':' + BANK), data = parseBank(bytes), live = liveBank(data), held = recoverHeld(data, ref);
  // The category list and its order remain exactly the 53 base categories, with no expansion packs.
  assert.equal(live.cats.length, 53, 'Review a changed base category set before syncing');
  const save = (file, text) => {const dest = path.join(hanna, file); fs.mkdirSync(path.dirname(dest), {recursive: true}); fs.writeFileSync(dest, text);};
  const source = JSON.stringify(live);
  save('data/reference/kunuz-bank-3147.js', bytes);
  save('data/source/reference-extract.json', source);
  const esbuild = require(path.join(hanna, 'node_modules/esbuild'));
  const runCli = (entry, name, args = [], env = {}) => {
    const outfile = path.join(hanna, 'packages/bank/dist', name + '.mjs');
    esbuild.buildSync({entryPoints: [path.join(hanna, entry)], outfile, bundle: true, platform: 'node', format: 'esm', target: 'node20', logLevel: 'warning'});
    cp.execFileSync(process.execPath, [outfile, ...args], {cwd: hanna, env: {...process.env, ...env}, stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 1 << 28, windowsHide: true});
  };
  runCli('packages/bank/src/cli.ts', 'cli', ['--rule', 'main live base rows only; held tombstones excluded; original category order and derived room ids']);
  // The importer emits a compact TypeScript category literal; the server's format gate pins Prettier layout.
  cp.execFileSync(process.execPath, [path.join(hanna, 'node_modules/prettier/bin/prettier.cjs'), '--write', 'apps/worker/src/generated/categories.ts'], {cwd: hanna, stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true});
  const lock = JSON.parse(fs.readFileSync(path.join(hanna, 'data/bank.lock.json'), 'utf8'));
  assert.equal(lock.rejectedCount, 0, 'The importer rejected a live row');
  const built = JSON.parse(fs.readFileSync(path.join(hanna, 'apps/worker/src/generated/bank.txt'), 'utf8'));
  assert.equal(built.qs.length, live.qs.length);
  assert.deepEqual(built.cats.map(c => c.id), live.cats.map(c => c[0]));
  const heldIds = new Set(held.flatMap(q => [q.appId, q.roomId]));
  const heldPrompts = new Set(held.map(q => q.promptSha256));
  built.qs.forEach((q, i) => {
    const row = live.qs[i];
    assert.equal(q.id, roomId(live.cats[row[0]][0], row[3]));
    assert.equal(q.prompt, row[3].trim());
    assert.deepEqual(q.options, row[4].map(s => s.trim()));
    assert.equal(q.answer, row[5]);
    assert.ok(!heldIds.has(q.id) && !heldPrompts.has(sha(q.prompt)), 'A held question reached the room bank');
  });
  runCli('packages/bank/src/inventory-cli.ts', 'inventory-cli', [], {HL_EZIK: ROOT});
  const record = {schema: 'hanna-room-bank-sync/1', source: BANK + ' (origin/main)', sourceSha256: sha(bytes), liveSourceSha256: sha(source), bankSha256: lock.generatedSha256, categories: live.cats.length, liveRows: live.qs.length, heldRows: held.length, held};
  save('data/room-bank-sync.json', JSON.stringify(record, null, 2) + '\n');
  console.log(JSON.stringify({sourceSha256: record.sourceSha256, liveSourceSha256: record.liveSourceSha256, bankSha256: record.bankSha256, categories: record.categories, liveRows: record.liveRows, heldRows: record.heldRows}));
  return record;
}
module.exports = {parseBank, isHeld, roomId, liveBank, recoverHeld, sync};
if (require.main === module) {
  const arg = (flag, fallback) => {const i = process.argv.indexOf(flag); return i < 0 ? fallback : process.argv[i + 1];};
  sync(path.resolve(arg('--hanna-root', path.join(ROOT, '../hanna-laha'))), arg('--ref', 'origin/main'));
}
